<?php declare(strict_types=1); ?>
<div class="ap-grid"><section class="ap-stack"><article class="panel"><header class="panel-head"><div><span class="eyebrow">GRNI and accruals</span><h2>Goods received, not invoiced</h2></div><span class="panel-meta"><?= count($grni) ?> PO(s)</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>PO</th><th>Supplier</th><th class="numeric">Received</th><th class="numeric">Invoiced</th><th class="numeric">GRNI</th><th>Action</th></tr></thead><tbody><?php foreach($grni as$g): $po=data_find('purchase_orders',$g['purchase_order_id']); ?><tr><td><?= h($po['po_number']??('#'.$g['purchase_order_id'])) ?></td><td><?= h(data_supplier_name($g['supplier_id'])) ?></td><td class="numeric"><?= money($g['received_value']) ?></td><td class="numeric"><?= money($g['invoiced_value']) ?></td><td class="numeric"><strong><?= money($g['grni_amount']) ?></strong></td><td><?php if($period&&can('accounts_payable.create')): ?><form method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="create_accrual"><input type="hidden" name="period_id" value="<?= (int)$period['id'] ?>"><input type="hidden" name="purchase_order_id" value="<?= (int)$g['purchase_order_id'] ?>"><input type="hidden" name="owner_id" value="<?= $owner ?>"><input type="hidden" name="reviewer_id" value="<?= $reviewer ?>"><input type="hidden" name="evidence_note" value="GRNI accrual created from accepted receipt value less non-void supplier invoices."><button class="mini-button">Create accrual</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></article>
<article class="panel"><header class="panel-head"><div><span class="eyebrow">Accounting periods</span><h2>Close governance</h2></div></header><?php foreach($periods as$p): ?><div class="ap-card"><header><div><strong><?= h($p['period_label']) ?></strong><small><?= h(date_us($p['period_start'])) ?> – <?= h(date_us($p['period_end'])) ?></small></div><?= badge($p['status']) ?></header><a class="mini-button primary" href="?tab=close&period=<?= (int)$p['id'] ?>">Open period</a></div><?php endforeach; ?></article></section>
<aside class="ap-stack"><article class="panel"><header class="panel-head"><div><span class="eyebrow">New period</span><h2>Create accounting period</h2></div></header><form class="ap-form" method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="create_period"><label><span>Company</span><select name="company_id"><?= company_options($company) ?></select></label><label><span>Period label</span><input name="period_label" value="<?= h(date('F Y')) ?>" required></label><label><span>Start</span><input type="date" name="period_start" value="<?= date('Y-m-01') ?>"></label><label><span>End</span><input type="date" name="period_end" value="<?= date('Y-m-t') ?>"></label><label><span>Owner</span><select name="owner_id"><?= user_options($owner) ?></select></label><label><span>Reviewer</span><select name="reviewer_id"><?= user_options($reviewer) ?></select></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required>Accounting period established for invoice cutoff, GRNI, accrual, settlement, reconciliation, and close certification.</textarea></label><?php if(can('accounts_payable.create')): ?><button class="button primary span-2">Create period</button><?php endif; ?></form></article>
<?php if($period): ?><article class="panel"><header class="panel-head"><div><span class="eyebrow">Selected period</span><h2><?= h($period['period_label']) ?></h2></div><?= badge($period['status']) ?></header><p><?= count(accounts_payable_accruals((int)$period['id'])) ?> accrual(s) · <?= count(accounts_payable_certifications((int)$period['id'])) ?> certification(s)</p><?php foreach(accounts_payable_accruals((int)$period['id']) as$a): ?><div class="ap-card"><header><strong><?= h($a['accrual_number']) ?></strong><?= badge($a['status']) ?></header><p><?= h(data_supplier_name($a['supplier_id'])) ?> · <?= money($a['accrual_amount']) ?></p><?php if($a['status']==='draft'&&can('accounts_payable.review')): ?><form method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="approve_accrual"><input type="hidden" name="accrual_id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="evidence_note" value="Independent accrual reviewer verified receipt, invoice, methodology, amount, and reversal date."><button class="mini-button">Approve accrual</button></form><?php endif; ?></div><?php endforeach; ?><div class="modal-actions"><?php if($period['status']==='open'&&can('accounts_payable.close')&&$owner===$periodReviewer): ?><form method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="close_period"><input type="hidden" name="period_id" value="<?= (int)$period['id'] ?>"><input type="hidden" name="target_status" value="soft_closed"><input type="hidden" name="reviewer_id" value="<?= $periodReviewer ?>"><input type="hidden" name="approver_id" value="<?= $periodApprover ?>"><input type="hidden" name="evidence_note" value="Soft close completed after invoice cutoff, payment, credit, GRNI, and reconciliation review."><button class="button secondary">Soft close</button></form><?php elseif($period['status']==='soft_closed'&&can('accounts_payable.close')&&$owner===$periodApprover): ?><form method="post" action="<?= h(app_url('accounts-payable-action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="close_period"><input type="hidden" name="period_id" value="<?= (int)$period['id'] ?>"><input type="hidden" name="target_status" value="hard_closed"><input type="hidden" name="reviewer_id" value="<?= $periodReviewer ?>"><input type="hidden" name="approver_id" value="<?= $periodApprover ?>"><input type="hidden" name="evidence_note" value="Controller certification completed after all accruals, payments, credits, and reconciliations were reviewed."><button class="button primary">Hard close and lock</button></form><?php endif; ?></div></article><?php endif; ?></aside></div>
